// Builds an install script that puts the whole app in its own Postgres schema, so it can live inside a
// Supabase project that already runs something else in "public" without touching it.
//   node scripts/schema-bundle.mjs nahal [--demo PASSWORD] > out.sql
// Then expose the schema to the API (Project Settings → Data API → Exposed schemas) and set NEXT_PUBLIC_DB_SCHEMA.
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));
const [schema = "nahal", ...rest] = process.argv.slice(2);
if (!/^[a-z_][a-z0-9_]*$/.test(schema) || schema === "public") throw new Error("schema name");
const demoIdx = rest.indexOf("--demo");
const demoPassword = demoIdx >= 0 ? rest[demoIdx + 1] : null;

const files = readdirSync(join(ROOT, "supabase", "migrations")).filter((f) => f.endsWith(".sql")).sort()
  .map((f) => join("supabase", "migrations", f));
if (demoPassword) files.push("supabase/seed/demo.sql", "supabase/seed/demo-accounts.sql");

function transform(sql) {
  return sql
    .replaceAll("public.", `${schema}.`)                 // every qualified object
    .replaceAll("schema public", `schema ${schema}`)     // grants / default privileges / loops
    .replaceAll("schemaname = 'public'", `schemaname = '${schema}'`)
    .replaceAll("on_auth_user_created", `${schema}_on_auth_user_created`)
    .replaceAll("__DEMO_PASSWORD__", demoPassword ?? "__DEMO_PASSWORD__");
  // note: "from public, anon" (the PUBLIC role) is intentionally left as is
}

let out = `-- Nahal CRM installed into schema "${schema}" (generated by scripts/schema-bundle.mjs).
-- Leaves the "public" schema, its tables, grants and the project's other users untouched.
create schema if not exists ${schema};
grant usage on schema ${schema} to anon, authenticated;
alter default privileges in schema ${schema} grant all on tables to authenticated;
alter default privileges in schema ${schema} grant all on sequences to authenticated;
alter default privileges in schema ${schema} grant execute on functions to authenticated;
`;
for (const f of files) out += `\n-- ===== ${f} =====\n` + transform(readFileSync(join(ROOT, f), "utf8"));

// In a shared project the sign-up trigger must never block the other app's users:
// people who are not on our invite list simply get no staff row (and therefore no access here).
out += `
-- ===== shared-project sign-up trigger: never blocks other users =====
create or replace function ${schema}.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare inv ${schema}.staff_invites;
begin
  begin
    select * into inv from ${schema}.staff_invites where email = lower(new.email);
    if found then
      insert into ${schema}.staff (id, email, full_name, role, cohort_scope, region_scope)
      values (new.id, lower(new.email), inv.full_name, inv.role, inv.cohort_scope, inv.region_scope);
      delete from ${schema}.staff_invites where email = inv.email;
    end if;
  exception when others then
    raise warning 'nahal staff onboarding skipped: %', sqlerrm;
  end;
  return new;
end $$;
revoke execute on function ${schema}.handle_new_user() from public, anon, authenticated;
grant select, insert, update, delete on all tables in schema ${schema} to authenticated;
grant usage, select on all sequences in schema ${schema} to authenticated;
notify pgrst, 'reload schema';
`;
process.stdout.write(out);
